import json
from collections import defaultdict

data = json.loads(context)

dates = defaultdict(list)
for row in data:
    dates[row['record_date']].append(row)

total_withdrawals = 0

for date, rows in dates.items():
    deposit = None
    withdrawal = None
    for row in rows:
        at = row['account_type']
        if 'Deposits' in at:
            deposit = int(row['open_today_bal'])
        elif 'Withdrawals' in at:
            withdrawal = int(row['open_today_bal'])
    if deposit is not None and withdrawal is not None:
        if deposit < withdrawal:
            total_withdrawals += withdrawal

print(FINAL(str(total_withdrawals)))
